    py: 'import sys\nd = sys.stdin.read().split()\nn, t = int(d[0]), int(d[1]); a = list(map(int, d[2:2 + n]))\nfirst = {}\nans = (-1, -1)\nfor j, x in enumerate(a):\n    if t - x in first:\n        ans = (first[t - x], j)\n        break\n    first.setdefault(x, j)\nprint(*ans)\n',
    java: 'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt(); long t = sc.nextLong();\n        Map<Long, Integer> first = new HashMap<>();\n        String ans = "-1 -1";\n        for (int j = 0; j < n; j++) {\n            long x = sc.nextLong();\n            Integer i = first.get(t - x);\n            if (i != null) { ans = i + " " + j; break; }\n            first.putIfAbsent(x, j);\n        }\n        System.out.println(ans);\n    }\n}\n',
    c: '#include <stdio.h>\n#include <stdlib.h>\n\n/* Open-addressing hash map from value -> first index */\n#define CAP (1 << 18)\nlong long keys[CAP]; int vals[CAP]; char used[CAP];\nunsigned hsh(long long k) { unsigned long long x = (unsigned long long)k * 11400714819323198485ull; return (unsigned)(x >> 46); }\nint find(long long k) { unsigned h = hsh(k); while (used[h] && keys[h] != k) h = (h + 1) & (CAP - 1); return (int)h; }\n\nint main(void) {\n    int n; long long t, x; scanf("%d %lld", &n, &t);\n    for (int j = 0; j < n; j++) {\n        scanf("%lld", &x);\n        int s = find(t - x);\n        if (used[s]) { printf("%d %d\\n", vals[s], j); return 0; }\n        s = find(x);\n        if (!used[s]) { used[s] = 1; keys[s] = x; vals[s] = j; }\n    }\n    printf("-1 -1\\n");\n    return 0;\n}\n',
